INSERT INTO examples (name, category, framework, files, dependencies, metadata) VALUES ('"theme-switch"', '"theming"', '"vanilla"', '{"demo.css": "@import \"https://unpkg.com/open-props/easings.min.css\";\n\n.sun-and-moon > :is(.moon, .sun, .sun-beams) {\n  transform-origin: center;\n}\n\n.sun-and-moon > :is(.moon, .sun) {\n  fill: var(--icon-fill);\n}\n\n.theme-toggle:is(:hover, :focus-visible) > .sun-and-moon > :is(.moon, .sun) {\n  fill: var(--icon-fill-hover);\n}\n\n.sun-and-moon > .sun-beams {\n  stroke: var(--icon-fill);\n  stroke-width: 2px;\n}\n\n.theme-toggle:is(:hover, :focus-visible) .sun-and-moon > .sun-beams {\n  stroke: var(--icon-fill-hover);\n}\n\n[data-theme=\"dark\"] .sun-and-moon > .sun {\n  transform: scale(1.75);\n}\n\n[data-theme=\"dark\"] .sun-and-moon > .sun-beams {\n  opacity: 0;\n}\n\n[data-theme=\"dark\"] .sun-and-moon > .moon > circle {\n  transform: translateX(-7px);\n}\n\n@supports (cx: 1) {\n  [data-theme=\"dark\"] .sun-and-moon > .moon > circle {\n    cx: 17;\n    transform: translateX(0);\n  }\n}\n\n@media (prefers-reduced-motion: no-preference) {\n  .sun-and-moon > .sun {\n    transition: transform .5s var(--ease-elastic-3);\n  }\n\n  .sun-and-moon > .sun-beams {\n    transition: transform .5s var(--ease-elastic-4), opacity .5s var(--ease-3);\n  }\n\n  .sun-and-moon .moon > circle {\n    transition: transform .25s var(--ease-out-5);\n  }\n\n  @supports (cx: 1) {\n    .sun-and-moon .moon > circle {\n      transition: cx .25s var(--ease-out-5);\n    }\n  }\n\n  [data-theme=\"dark\"] .sun-and-moon > .sun {\n    transition-timing-function: var(--ease-3);\n    transition-duration: .25s;\n    transform: scale(1.75);\n  }\n\n  [data-theme=\"dark\"] .sun-and-moon > .sun-beams {\n    transition-duration: .15s;\n    transform: rotateZ(-25deg);\n  }\n\n  [data-theme=\"dark\"] .sun-and-moon > .moon > circle {\n    transition-duration: .5s;\n    transition-delay: .25s;\n  }\n}\n", "demo.html": "<button class=\"theme-toggle\" id=\"theme-toggle\" title=\"Toggles light & dark\" aria-label=\"auto\" aria-live=\"polite\">\n  <svg class=\"sun-and-moon\" aria-hidden=\"true\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\">\n    <mask class=\"moon\" id=\"moon-mask\">\n      <rect x=\"0\" y=\"0\" width=\"100%\" height=\"100%\" fill=\"white\" />\n      <circle cx=\"24\" cy=\"10\" r=\"6\" fill=\"black\" />\n    </mask>\n    <circle class=\"sun\" cx=\"12\" cy=\"12\" r=\"6\" mask=\"url(#moon-mask)\" fill=\"currentColor\" />\n    <g class=\"sun-beams\" stroke=\"currentColor\">\n      <line x1=\"12\" y1=\"1\" x2=\"12\" y2=\"3\" />\n      <line x1=\"12\" y1=\"21\" x2=\"12\" y2=\"23\" />\n      <line x1=\"4.22\" y1=\"4.22\" x2=\"5.64\" y2=\"5.64\" />\n      <line x1=\"18.36\" y1=\"18.36\" x2=\"19.78\" y2=\"19.78\" />\n      <line x1=\"1\" y1=\"12\" x2=\"3\" y2=\"12\" />\n      <line x1=\"21\" y1=\"12\" x2=\"23\" y2=\"12\" />\n      <line x1=\"4.22\" y1=\"19.78\" x2=\"5.64\" y2=\"18.36\" />\n      <line x1=\"18.36\" y1=\"5.64\" x2=\"19.78\" y2=\"4.22\" />\n     </g>\n  </svg>\n</button>", "demo.js": "const storageKey = ''theme-preference''\n\nconst onClick = () => {\n  // flip current value\n  theme.value = theme.value === ''light''\n    ? ''dark''\n    : ''light''\n\n  setPreference()\n}\n\nconst getColorPreference = () => {\n  if (localStorage.getItem(storageKey))\n    return localStorage.getItem(storageKey)\n  else\n    return window.matchMedia(''(prefers-color-scheme: dark)'').matches\n      ? ''dark''\n      : ''light''\n}\n\nconst setPreference = () => {\n  localStorage.setItem(storageKey, theme.value)\n  reflectPreference()\n}\n\nconst reflectPreference = () => {\n  document.firstElementChild\n    .setAttribute(''data-theme'', theme.value)\n\n  document\n    .querySelector(''#theme-toggle'')\n    ?.setAttribute(''aria-label'', theme.value)\n}\n\nconst theme = {\n  value: getColorPreference(),\n}\n\n// set early so no page flashes / CSS is made aware\nreflectPreference()\n\nwindow.onload = () => {\n  // set on load so screen readers can see latest value on the button\n  reflectPreference()\n\n  // now this script can find and listen for clicks on the control\n  document\n    .querySelector(''#theme-toggle'')\n    .addEventListener(''click'', onClick)\n}\n\n// sync with system changes\nwindow\n  .matchMedia(''(prefers-color-scheme: dark)'')\n  .addEventListener(''change'', ({matches:isDark}) => {\n    theme.value = isDark ? ''dark'' : ''light''\n    setPreference()\n  })"}', '{}', '{"original_path": "patterns/theming/theme-switch"}'), ('"badges"', '"web-apps"', '"vanilla"', '{"demo (2).png": "\ufffdPNG\r\n\u001a\n\u0000\u0000\u0000\rIHDR\u0000\u0000\u0002\u0000\u0000\u0000\u0002\u0000\b\u0006\u0000\u0000\u0000\ufffdx\ufffd\ufffd\u0000\u0000\u0000\tpHYs\u0000\u0000;\u000e\u0000\u0000;\u000e\u0001\u0336\ufffd\ufffd\u0000\u0000\u0000\u0019tEXtSoftware\u0000www.inkscape.org\ufffd\ufffd<\u001a\u0000\u0000 \u0000IDATx\ufffd\ufffd\ufffdw|\u001c\u05797\ufffd\ufffd3e\ufffd\ufffde[\ufffd\u0018Y\ufffd-\ufffd\u0606\u0018\f\u0004[\ufffd\ufffd\ufffd\u000b.\ufffd\ufffd\ufffd\\\u0002$\ufffd\ufffdp\u0013\ufffd\ufffd\u0710\ufffd:\ufffd\ufffd\ufffdBH\ufffd\ufffd\ufffd`R\b\ufffd@\b\u0018C \t-!\u0010 \u0006Ls\ufffde\ufffd\u0576\ufffd9\ufffd\ufffd\ufffdJ\ufffd\ufffdvgf\ufffd\ufffd\u76cf\ufffd%\u035cyv\ufffd\ufffd\ufffd\ufffd)\ufffd\u0001\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufffd\u0010B\b!\ufff